from pathlib import Path
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib.colors import HexColor
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import Paragraph,Table,TableStyle
from xml.sax.saxutils import escape
import re
ROOT=Path(__file__).resolve().parents[1]
css=ROOT/'src/styles/typography.css'
CSS=css.read_text() if css.exists() else '--type-print-body: 11pt; --type-print-h1: 20pt; --type-print-h2: 15pt;'
S,T,U=[float(re.search(r'--type-print-'+k+r':\s*([\d.]+)pt',CSS).group(1)) for k in ('body','h1','h2')]
for f,n in [('D','DejaVuSans.ttf'),('B','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(f,'/usr/share/fonts/truetype/dejavu/'+n))
INK,NAVY,LINE,PALE=map(HexColor,['#182D3E','#245A82','#AABDCB','#EDF4F8'])
W,H=A4; L=42; R=W-L; WIDTH=R-L

def tr(en,kk):return en if lang=='en' else kk
def p(t,b=False,size=S,color=INK):return Paragraph(escape(t),ParagraphStyle('p',fontName='B' if b else 'D',fontSize=size,leading=size*1.35,textColor=color))
def draw(t,b=False,size=S,color=INK,x=L,gap=8):
 global y
 q=p(t,b,size,color);_,h=q.wrap(R-x,H);q.drawOn(c,x,y-h);y-=h+gap

def start(name,title,pages,folder='selfcare',official=False):
 global c,doc_title,total,foot
 doc_title=title;total=pages;foot=tr('Family resource, not an official form','Отбасына арналған материал, ресми бланк емес') if official else tr('Not a diagnostic tool','Диагностикалық құрал емес')
 path=ROOT/'public/downloads'/folder/f'{name}-{lang}.pdf';path.parent.mkdir(parents=True,exist_ok=True);c=canvas.Canvas(str(path),pagesize=A4,invariant=1);c.setTitle(title);c.setAuthor('Autism Hub Kazakhstan')
def header(n,sub):
 global y
 c.setFillColor(NAVY);c.rect(0,H-12,W,12,stroke=0,fill=1);y=H-34
 draw('Autism Hub Kazakhstan / '+tr('Resources for parents','Ата-аналарға арналған материалдар'),True,S,NAVY);draw(doc_title,True,T,NAVY);draw(sub,True,U,NAVY);c.setStrokeColor(LINE);c.line(L,43,R,43);c.setFont('D',S);c.setFillColor(INK);c.drawString(L,26,'AutismHub | '+foot);c.drawRightString(R,26,f'{n} / {total}')
def heading(t):draw(t,True,U,NAVY)
def table(head,rows,widths,blank=0,minrow=0):
 global y
 data=[[p(x,True,S,NAVY) for x in head]]+[[p(x) for x in row] for row in rows]; heights=[]
 for i,row in enumerate(data):
  heights.append(max([max(q.wrap(w-16,H)[1]+16 for q,w in zip(row,widths)),blank if i else 0,minrow if i else 0]))
 t=Table(data,colWidths=widths,rowHeights=heights);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('GRID',(0,0),(-1,-1),.7,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]));_,h=t.wrap(WIDTH,H);t.drawOn(c,L,y-h);y-=h+12

def field(t,n=1,spacing=24):
 global y
 draw(t,True,gap=4);c.setStrokeColor(LINE)
 for _ in range(n):c.line(L,y-12,R,y-12);y-=spacing
 y-=4

def check(t):
 c.setStrokeColor(NAVY);c.rect(L,y-13,11,11,fill=0,stroke=1);draw(t,x=L+24,gap=6)
def blankcheck(n):
 global y
 for _ in range(n):
  c.setStrokeColor(NAVY);c.rect(L,y-16,12,12,stroke=1,fill=0);c.setStrokeColor(LINE);c.line(L+25,y-16,R,y-16);y-=30

def end():
 assert y>55,(lang,doc_title,c.getPageNumber(),y);c.showPage()
def finish():c.save()

def toilet():
 start('toileting-diary',tr('Toileting observation diary','Дәретхана дағдыларын бақылау күнделігі'),2,'toileting')
 heads=tr(['Time','Event','Support','Observations'],['Уақыт','Оқиға','Қолдау','Бақылау']);widths=[60,156,116,WIDTH-332]
 header(1,tr('Completed example','Толтырылған үлгі'));draw(tr('Observe the usual routine for a few days. Seven days is a convenient guide, not a required period. Record facts, support and visible signs of discomfort.','Бірнеше күн бойы әдеттегі күн тәртібін бақылаңыз. Жеті күн - ыңғайлы бағдар, міндетті мерзім емес. Нақты оқиғаларды, көрсетілген көмекті және жайсыздықтың байқалған белгілерін жазыңыз.'));draw(tr('Date: illustrative example. All entries are fictional.','Күні: шартты үлгі. Барлық жазба ойдан алынған.'),True)
 table(heads,tr([['08:10','Bowel movement in nappy','No prompt','Strained.'],['10:25','Urination outside toilet','No prompt','No signal noticed.'],['12:40','Urination in toilet','Reminder','No visible discomfort.']],[['08:10','Жөргекке нәжіс шығарды','Бағыттаушы көмексіз','Күшенді.'],['10:25','Дәретханадан тыс зәр шығарды','Бағыттаушы көмексіз','Белгі байқалмады.'],['12:40','Дәретханада зәр шығарды','Еске салу','Көзге көрінетін жайсыздық жоқ.']]),widths,minrow=64)
 heading(tr('How to use the diary','Күнделікті қалай пайдалану керек'));draw(tr('Record urination and bowel movements separately. If no signal was noticed, do not assume there was none. Do not change drinking, sleep or toilet access for the sake of recording.','Зәр шығаруды және үлкен дәретті бөлек белгілеңіз. Белгі байқалмаса, ол болмады деп қорытынды жасамаңыз. Жазба үшін су ішуді, ұйқыны немесе дәретханаға бару мүмкіндігін өзгертпеңіз.'));draw(tr('Consult a doctor if there is pain, constipation or new urinary symptoms. Sudden inability to urinate requires emergency medical attention. Do not delay seeking help to complete the diary.','Ауырсыну, іш қату немесе зәр шығаруға қатысты жаңа белгілер болса, дәрігерге жүгініңіз. Кенеттен зәр шығара алмау шұғыл медициналық көмекті қажет етеді. Күнделікті толтыру үшін медициналық көмекке жүгінуді кейінге қалдырмаңыз.'));draw(tr('Keep records private. Do not post them in group chats or on social media. Share only necessary information with the specialist.','Жазбаларды құпия сақтаңыз. Оларды ортақ чаттарда немесе әлеуметтік желілерде жарияламаңыз. Маманға қажетті ақпаратты ғана беріңіз.'));end()
 header(2,tr('Blank observation sheet','Бос бақылау парағы'));draw(tr('Date: ____________________','Күні: ____________________'),True);draw(tr('Print this page for each observation day. Complete only the rows you need.','Әр бақылау күніне осы бетті басып шығарыңыз. Қажетті жолдарды ғана толтырыңыз.'));table(heads,[['']*4 for _ in range(8)],widths,blank=48);field(tr('Additional observations or questions for the specialist:','Қосымша бақылаулар немесе маманға сұрақтар:'),2);draw(tr('Records stay with the family. Do not delay medical care to complete the sheet.','Жазбалар отбасында сақталады. Парақты толтыру үшін медициналық көмекті кейінге қалдырмаңыз.'));end();finish()

def prompting():
 start('prompting-diary',tr('Independence and prompting diary','Дербестік және бағыттаушы көмек күнделігі'),2)
 heads=tr(['Day','Total','Independent','Prompted','Not completed'],['Күн','Барлығы','Дербес','Бағыттаушы көмекпен','Орындалмады']);widths=[60,80,113,133,WIDTH-386]
 header(1,tr('Completed example','Толтырылған үлгі'));draw(tr('Skill: put a light, unbreakable cup in an accessible place after drinking.','Дағды: сусын ішкеннен кейін жеңіл, сынбайтын кесені қолжетімді жерге қою.'),True);draw(tr('Fictional data. Five opportunities per day are an illustration, not a norm.','Деректер ойдан алынған. Күніне бес мүмкіндік тек мысал ретінде берілген, норма емес.'));days=tr(['Mon','Tue','Wed','Thu','Fri'],['Дс','Сс','Ср','Бс','Жм']);table(heads,[[d,*v] for d,v in zip(days,[['5','1','4','0'],['5','2','3','0'],['5','3','2','0'],['5','4','0','1'],['5','4','1','0']])],widths,minrow=34)
 heading(tr('How to interpret the records','Жазбаларды қалай түсінуге болады'));draw(tr('On Thursday the child acted independently four times and did not complete the action once. Do not repeat the task just to obtain a result. Refusal is not an error.','Бейсенбіде бала әрекетті төрт рет дербес орындады, бір рет орындамады. Нәтиже алу үшін тапсырманы қайта орындатудың қажеті жоқ. Бас тарту қателік емес.'));draw(tr('Independence: divide the number of actions completed without an extra prompt by the number of observed opportunities and multiply by 100%. Keep necessary ongoing adaptations available.','Дербестік: қосымша бағыттаушы көмексіз орындалған әрекеттер санын байқалған мүмкіндіктер санына бөліп, 100%-ға көбейтіңіз. Қажетті тұрақты бейімдеулер қолжетімді болып қала береді.'));draw(tr('If independence increases and the child is comfortable, try reducing unnecessary help. If difficulties arise, reconsider the conditions. Do not remove AAC or necessary adaptations.','Дербестік артып, бала өзін жайлы сезінсе, артық көмекті азайтып көріңіз. Қиындық туындаса, жағдайды қайта қарастырыңыз. AAC пен қажетті бейімдеулерді алып тастамаңыз.'));draw(tr('Observe everyday situations rather than creating a required number of attempts. Keep records private.','Күнделікті жағдайларды бақылаңыз, міндетті әрекет санын белгілемеңіз. Жазбаларды құпия сақтаңыз.'));end()
 header(2,tr('Blank observation sheet','Бос бақылау парағы'));draw(tr('Skill: __________________________________________________','Дағды: __________________________________________________'));draw(tr('Period: ____________________    Conditions: ___________________','Кезең: ____________________    Жағдай: ___________________'));table(heads,[['']*5 for _ in range(7)],widths,blank=42);field(tr('What helped? Reasons for refusal, comfort, type of prompt:','Не көмектесті? Бас тарту себептері, жайлылық, көмек түрі:'),3);draw(tr('Complete only useful rows. Do not grade the child. Do not delay necessary help for the sake of observation.','Пайдалы жолдарды ғана толтырыңыз. Балаға баға қоймаңыз. Бақылау үшін қажетті көмекті кешіктірмеңіз.'));end();finish()

def video():
 start('video-modeling-plan',tr('Video preparation plan and observation diary','Бейне дайындау жоспары және бақылау күнделігі'),4)
 heads=tr(['Step','What to show'],['Қадам','Нені көрсету керек']); widths=[65,WIDTH-65]
 header(1,tr('Video plan: completed example','Бейне жоспары: толтырылған үлгі'));draw(tr('Skill: fold a small towel in a familiar, comfortable way.','Дағды: шағын сүлгіні үйреншікті, ыңғайлы тәсілмен бүктеу.'));draw(tr('Format: demonstration using an adult’s hands. Short separate clips if needed. All examples in this document are fictional.','Формат: ересек адамның қолымен көрсету. Қажет болса, қысқа бөлек үзінділер. Құжаттағы барлық мысал ойдан алынған.'));table(heads,[[str(i+1),s] for i,s in enumerate(tr(['Place the towel on an accessible table.','Spread the fabric and show the edges.','Fold the towel in half.','Put the folded towel on the shelf.'],['Сүлгіні қолжетімді үстелге қойыңыз.','Матаны жазып, шеттерін көрсетіңіз.','Сүлгіні екіге бүктеңіз.','Бүктелген сүлгіні сөреге қойыңыз.']))],widths,minrow=32);heading(tr('Preparation','Дайындық'));draw(tr('A similar towel, accessible table and shelf, and a stable phone. The camera shows hands and objects. Do not film the child.','Ұқсас сүлгі, қолжетімді үстел мен сөре, орнықты телефон. Камера қолдар мен заттарды көрсетеді. Баланы түсірмейміз.'));heading(tr('After viewing','Көргеннен кейін'));draw(tr('Offer a chance to try. If needed, show one step or help. Allow another comfortable way of folding. If the child refuses, stop the attempt.','Балаға орындап көруді ұсыныңыз. Қажет болса, бір қадамды көрсетіңіз немесе көмектесіңіз. Бүктеудің басқа ыңғайлы тәсіліне рұқсат етіңіз. Бала бас тартса, әрекетті тоқтатыңыз.'));draw(tr('There is no required viewing time. Consider comfort, safety and task accessibility.','Міндетті көру уақытын белгілеудің қажеті жоқ. Жайлылықты, қауіпсіздікті және тапсырманың қолжетімділігін ескеріңіз.'));end()
 header(2,tr('Video plan: blank sheet','Бейне жоспары: бос парақ'));field(tr('Skill and goal','Дағды мен мақсат'),2);field(tr('What already works? What needs adapting?','Қазір не қолынан келеді? Нені бейімдеу керек?'),2);field(tr('Format, model, objects and camera angle','Формат, үлгі көрсететін адам, заттар және түсіру ракурсы'));table(heads,[[str(i),''] for i in range(1,5)],widths,blank=51);field(tr('How will practice and help be offered?','Жаттығу мен көмек қалай ұсынылады?'));draw(tr('Where possible, film an adult or objects. Consider participants’ consent, access to the recording and deletion date. Do not film intimate activities.','Мүмкіндігінше ересек адамды немесе заттарды түсіріңіз. Қатысушылардың келісімін, жазбаға қолжетімділікті және өшіру мерзімін ескеріңіз. Жеке гигиенаға қатысты әрекеттерді түсірмеңіз.'));end()
 heads=tr(['Situation','Video and support','Outcome and comfort'],['Жағдай','Бейне және көмек','Нәтиже мен жайлылық']); widths=[120,180,WIDTH-300]
 header(3,tr('Observation: completed example','Бақылау: толтырылған үлгі'));draw(tr('Skill: fold a towel. Fictional entries, not research data or developmental norms.','Дағды: сүлгі бүктеу. Шартты жазбалар, зерттеу деректері немесе даму нормасы емес.'));table(heads,tr([['Home, familiar towel','Adult started video and pointed to fabric edge.','Folded after gesture. Asked to finish.'],['Home, familiar towel','Started video independently.','Folded without adult help.'],['Home, different towel','Needed demonstration of one step.','Folded with help.'],['Later, usual situation','Video was available.','Declined. Practice stopped.']],[['Үйде, таныс сүлгі','Ересек бейнені қосып, матаның шетін көрсетті.','Ымнан кейін бүктеді. Аяқтауды сұрады.'],['Үйде, таныс сүлгі','Бейнені өзі қосты.','Ересек адамның көмегінсіз бүктеді.'],['Үйде, басқа сүлгі','Бір қадамды көрсету қажет болды.','Көмекпен бүктеді.'],['Кейін, әдеттегі жағдай','Бейне қолжетімді болды.','Бас тартты. Жаттығу жалғасқан жоқ.']]),widths,minrow=47);heading(tr('Interpreting the outcome','Нәтижені түсіну'));draw(tr('Using video independently may be a useful adaptation. Record actions after an adult gesture separately. Refusal is not the child’s error.','Бейнені дербес пайдалану пайдалы бейімдеу болуы мүмкін. Ересектің ымынан кейінгі әрекетті бөлек белгілеңіз. Бас тартуды баланың қателігі деп есептемеңіз.'));heading(tr('Generalisation and maintenance','Дағдыны басқа жағдайға көшіру және сақтау'));draw(tr('Check in ordinary situations with another object and after time has passed, keeping needed support. If there was no opportunity to observe, do not record failure.','Қажетті қолдауды сақтай отырып, басқа затпен әдеттегі жағдайда және біраз уақыт өткен соң тексеріңіз. Бақылау мүмкіндігі болмаса, оны сәтсіздік ретінде жазбаңыз.'));draw(tr('Reconsider the format if the recording is unhelpful or uncomfortable. Do not create a required number of attempts.','Жазба көмектеспесе немесе жайсыздық тудырса, форматты қайта қарастырыңыз. Міндетті әрекет санын белгілемеңіз.'));end()
 header(4,tr('Observation: blank sheet','Бақылау: бос парақ'));field(tr('Skill and observation period','Дағды және бақылау кезеңі'));table(tr(['Date and situation','Video and support','Outcome and comfort'],['Күні және жағдай','Бейне және көмек','Нәтиже мен жайлылық']),[['']*3 for _ in range(6)],widths,blank=55);field(tr('Generalisation, maintenance, what to change','Басқа жағдайға көшіру, сақтау, нені өзгерту керек'),2);draw(tr('Complete only useful rows. Keep records private. Do not post information about the child in group chats or on social media.','Пайдалы жолдарды ғана толтырыңыз. Жазбаларды құпия сақтаңыз. Бала туралы мәліметті ортақ чаттарда немесе әлеуметтік желілерде жарияламаңыз.'));end();finish()

def selfmanage():
 start('self-management-plan',tr('My Independence Plan','Менің дербестік жоспарым'),4)
 header(1,tr('Individual plan: example','Жеке жоспар: үлгі'));draw(tr('All examples are fictional. Choose the goal and type of support together with the child.','Барлық мысал ойдан алынған. Мақсат пен көмек тәсілін баламен бірге таңдаңыз.'));table(tr(['What we plan','Example'],['Нені жоспарлаймыз','Үлгі']),tr([['My goal','Pack the things I need in my school bag.'],['My choice','It is easier to prepare in the evening using a picture checklist.'],['Tool','List next to my bag. Things are within reach.'],['Support that stays','I can ask for help finding a textbook or lifting heavy things.'],['What we want to change','Fewer reminders about each item if the list helps.']],[['Менің мақсатым','Мектепке қажетті заттарды сөмкеме жинау.'],['Менің таңдауым','Заттарды кешке суретті тізіммен дайындаған ыңғайлы.'],['Құрал','Тізім сөмкенің жанында. Заттар қолжетімді жерде.'],['Сақталатын көмек','Оқулықты табуға немесе ауыр заттарға көмектесуді сұрай аламын.'],['Нені өзгерткіміз келеді','Тізім көмектессе, әр затты азырақ еске салу.']]),[150,WIDTH-150]);heading(tr('Example checklist for the chosen day','Таңдалған күнге арналған тізім үлгісі'))
 for t in tr(['Check the timetable.','Pack the necessary notebooks and textbooks.','Take the pencil case.','Take the water bottle.'],['Сабақ кестесін тексеру.','Қажетті дәптерлер мен оқулықтарды салу.','Қаламсауытты алу.','Су құтысын алу.']):check(t)
 draw(tr('The list can change. Asking for help and refusing are not errors. Water, food or rest do not have to be earned.','Тізімді өзгертуге болады. Көмек сұрау және бас тарту қателік емес. Су, тамақ немесе демалыс алу үшін тапсырма орындау міндетті емес.'));end()
 header(2,tr('Individual plan: blank sheet','Жеке жоспар: бос парақ'));field(tr('My goal and why it matters to me','Менің мақсатым және оның маған не үшін қажет екені'),2);field(tr('Which tool do I choose?','Қандай құралды таңдаймын?'));field(tr('What support do I want to keep?','Қандай көмекті сақтағым келеді?'),2);heading(tr('My checklist','Менің әрекеттер тізімім'));blankcheck(5);field(tr('How will I know the tool helps?','Құралдың көмектесетінін қалай білемін?'));draw(tr('The goal, list or type of support can change. Complete only useful fields.','Мақсатты, тізімді немесе көмек тәсілін өзгертуге болады. Пайдалы өрістерді ғана толтырыңыз.'));end()
 header(3,tr('Observation: completed example','Бақылау: толтырылған үлгі'));draw(tr('Skill: pack a school bag. Fictional situations, not research data or developmental norms.','Дағды: мектеп сөмкесін дайындау. Шартты жағдайлар, зерттеу деректері немесе даму нормасы емес.'));table(tr(['Situation','Tool and support','Next step'],['Жағдай','Құрал және көмек','Келесі шешім']),tr([['Mon evening','Adult reminded the child of the list. Packed with help.','Keep list beside bag.'],['Tue evening','Opened list independently and asked for help finding a textbook.','Keep help available.'],['Different timetable','List was out of date. Planned together.','Update list.'],['Tiredness','Postponed packing. Adult helped.','Reconsider workload and timing.']],[['Дс, кешке','Ересек тізімді еске салды. Көмекпен жинады.','Тізімді сөмке жанында қалдыру.'],['Сс, кешке','Тізімді өзі ашып, оқулықты табуға көмек сұрады.','Көмек сұрау мүмкіндігін сақтау.'],['Басқа кесте','Тізім ескірді. Бірге жоспарлады.','Тізімді жаңарту.'],['Шаршау','Жинауды кейінге қалдырды. Ересек көмектесті.','Жүктеме мен уақытты қайта қарау.']]),[100,218,WIDTH-318]);heading(tr('What to look for','Неге назар аудару керек'));draw(tr('Record independent use of the list separately from actions after a reminder. Asking for help may be an expression of independence.','Тізімге дербес жүгінуді еске салудан кейінгі әрекеттен бөлек жазыңыз. Көмек сұрау дербестіктің көрінісі болуы мүмкін.'));draw(tr('Maintenance: does the list still help later? Generalisation: is it useful when the timetable changes? Do not create extra attempts for recording.','Сақтау: тізім біраз уақыттан кейін де көмектесе ме? Басқа жағдайға көшіру: кесте өзгергенде қолдануға ыңғайлы ма? Жазба үшін артық әрекет жасатпаңыз.'));draw(tr('If the child is uncomfortable, change the tool, return to joint planning or postpone the task. Do not reduce necessary care or supervision.','Балаға ыңғайсыз болса, құралды өзгертуге, бірлесіп жоспарлауға оралуға немесе тапсырманы кейінге қалдыруға болады. Қажетті күтім мен қадағалауды азайтпаңыз.'));end()
 header(4,tr('Observation: blank sheet','Бақылау: бос парақ'));field(tr('Skill and observation period','Дағды және бақылау кезеңі'));table(tr(['Date and situation','Tool, support and comfort','Next step'],['Күні және жағдай','Құрал, көмек және жайлылық','Келесі шешім']),[['']*3 for _ in range(6)],[105,224,WIDTH-329],blank=55);field(tr('What became easier? What should change?','Не ыңғайлы болды? Нені өзгерту керек?'),2);draw(tr('Keep records with the family. Do not grade the child. If no opportunity arose, do not record failure.','Жазбаларды отбасында сақтаңыз. Балаға баға қоймаңыз. Бақылау мүмкіндігі болмаған жағдайды сәтсіздік ретінде жазбаңыз.'));end();finish()

def special():
 start('special-pedagog-choice',tr('Choosing a special educator','Арнайы педагогті таңдау'),4,official=True)
 header(1,tr('Checklist before starting sessions','Сабақ басталғанға дейінгі тексеру тізімі'));draw(tr('Tick what you have clarified. An unchecked item means the question is still open, not that the specialist is incompetent.','Анықтаған тармақтарды белгілеңіз. Белгі қойылмаса, сұрақ әлі ашық деген сөз, маманның біліксіз екенін білдірмейді.'))
 for t in tr(['Relevant education and qualifications clarified.','Position, role and scope of competence understood.','Experience with the chosen educational task.','Initial educational assessment completed.','Goals agreed with the family and child in an accessible way.','Methods and necessary adaptations explained.','AAC, requests for help, breaks and refusal are accessible.','Comfort, consent and safety are considered.','A way to assess progress and generalisation is agreed.','Conditions and review date are agreed.'],['Бейіндік білімі мен біліктілігі анықталды.','Лауазымы, рөлі және құзырет шегі түсінікті.','Таңдалған оқу міндетімен жұмыс тәжірибесі бар.','Бастапқы педагогикалық бағалау жүргізілді.','Мақсаттар отбасымен және баламен қолжетімді түрде келісілді.','Әдістер мен қажетті бейімдеулер түсіндірілді.','AAC, көмек сұрау, үзіліс және бас тарту қолжетімді.','Жайлылық, келісім және қауіпсіздік ескеріледі.','Ілгерілеу мен дағдыны басқа жағдайға көшіруді бағалау тәсілі бар.','Бағдарламаны қайта қарау шарттары мен күні келісілді.']):check(t)
 heading(tr('When to reconsider the service','Қызметтен қашан бас тартқан жөн'));draw(tr('Promises to cure autism, coercion, restraint to obtain an answer, or restricting communication or basic needs require particular caution. One serious safety violation may be enough to stop sessions.','Аутизмді емдеп жазуға уәде беру, мәжбүрлеу, жауап алу үшін ұстап тұру, коммуникацияны немесе негізгі қажеттіліктерді шектеу ерекше сақтықты талап етеді. Қауіпсіздіктің бір елеулі бұзылуы сабақтарды тоқтатуға жеткілікті болуы мүмкін.'));draw(tr('The number of ticks is not a rating of qualifications or support quality.','Белгі саны маманның біліктілігіне немесе көмек сапасына қойылған баға емес.'));end()
 header(2,tr('Questions for the first consultation','Алғашқы кеңеске арналған сұрақтар'))
 for t in tr(['What can the child already do? What prevents participation?','Which goal matters to the child and family?','Which method do you propose and why?','How will AAC, help and the right to a break remain available?','How will outcomes be measured at school and home?','When and on what grounds will the programme change?'],['Бала қазір не істей алады? Қатысуына не кедергі?','Бала мен отбасы үшін қандай мақсат маңызды?','Қандай әдісті ұсынасыз және неге?','AAC, көмек және үзіліс құқығы қалай сақталады?','Нәтиже мектепте және үйде қалай бағаланады?','Бағдарлама қашан және қандай негізде өзгертіледі?']):field(t,2,spacing=24)
 draw(tr('If the service is paid, clarify the cost, payment and cancellation terms. Discuss who can access records about the child.','Қызмет ақылы болса, құнын, төлем және бас тарту шарттарын нақтылаңыз. Бала туралы жазбаларға кім қол жеткізетінін талқылаңыз.'));end()
 header(3,tr('Individual plan: completed example','Жеке жоспар: толтырылған үлгі'));draw(tr('All figures and circumstances are fictional. Goal: prepare materials for a familiar task.','Барлық сандар мен жағдайлар ойдан алынған. Мақсат: таныс тапсырмаға материалдар дайындау.'));table(tr(['Part of plan','Example'],['Жоспар бөлігі','Үлгі']),tr([['Baseline','Two of five steps completed without additional adult help.'],['Goal','Prepare materials using an accessible list with fewer unnecessary reminders.'],['Method','Demonstration, task analysis, reducing unnecessary prompts.'],['Support','Visual list, comfortable workspace, access to AAC and help.'],['Observation','Independent steps, prompts, comfort and requests for help.'],['Review','Check usability in class and when tasks change. Revise plan if needed.']],[['Бастапқы деңгей','Бес қадамның екеуі ересектің қосымша көмегінсіз орындалды.'],['Мақсат','Қолжетімді тізіммен материалдарды артық еске салусыз дайындау.'],['Әдіс','Көрсету, тапсырманы қадамдарға бөлу, артық бағыттаушы көмекті азайту.'],['Қолдау','Көрнекі тізім, ыңғайлы жұмыс орны, AAC пен көмекке қолжетімділік.'],['Бақылау','Дербес қадамдар, бағыттаушы көмек, жайлылық және көмек сұрау.'],['Қайта қарау','Сыныпта және тапсырма өзгергенде тізімнің ыңғайлылығын тексеру. Қажет болса, жоспарды өзгерту.']]),[128,WIDTH-128]);draw(tr('Do not remove necessary adaptations for the sake of results. Asking for help and refusing are not errors. The figures do not set a norm or learning deadline.','Нәтиже үшін қажетті бейімдеулерді алып тастамаңыз. Көмек сұрау және бас тарту қателік емес. Сандар норма немесе оқыту мерзімін белгілемейді.'));end()
 header(4,tr('Agreeing goals and reviewing outcomes','Мақсаттарды келісу және нәтижені бағалау'))
 for t,n in tr([('Date and participants',1),('Meaningful goal and baseline abilities',2),('Method, conditions and necessary support',2),('How can the child ask for help or refuse?',1),('How will outcomes, comfort and generalisation be observed?',2),('Review date and decisions',2)],[('Талқылау күні және қатысушылар',1),('Маңызды мақсат және бастапқы мүмкіндіктер',2),('Әдіс, жағдай және қажетті көмек',2),('Бала қалай көмек сұрайды немесе бас тартады?',1),('Нәтиже, жайлылық және басқа жағдайға көшіру қалай бақыланады?',2),('Қайта қарау күні және қабылданған шешімдер',2)]):field(t,n,spacing=24)
 draw(tr('Keep the completed sheet private. This is a discussion resource, not an official individual development programme form, diagnostic tool or educator certification.','Толтырылған парақты құпия сақтаңыз. Бұл талқылауға арналған материал, жеке дамыту бағдарламасының ресми бланкісі, диагностикалық құрал немесе педагогті аттестаттау құжаты емес.'));end();finish()

